using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.UI;
using UnityEngine.UI;

public sealed class ExpeditionGame : MonoBehaviour
{
    enum Terrain { Sea, Plains, Forest, Desert, Mountain }
    sealed class Site { public Vector2Int p; public string name; public int gold; public bool found; public Color color; public GameObject marker; }
    const int W=34,H=22;
    readonly Dictionary<Vector2Int,GameObject> fog=new(); readonly List<Site> sites=new(); readonly List<GameObject> world=new();
    Terrain[,] map; Vector2Int pos; int provisions,morale,gold,discoveries,days; bool title=true,ended,paused; float moveCooldown,kick,pulse;
    Text hud,message,objective,prompt,terrainReadout; Image provisionBar,moraleBar; GameObject explorer,titlePanel,endPanel,pausePanel,trailRoot; Camera cam; Sprite square,circle,diamond; System.Random rng; AudioSource sfx,ambient; Vector3 cameraTarget;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){if(FindFirstObjectByType<ExpeditionGame>()==null)new GameObject("Atlas of the Seventh Sun").AddComponent<ExpeditionGame>();}
    void Awake(){Application.targetFrameRate=60;square=MakeSprite(0);circle=MakeSprite(1);diamond=MakeSprite(2);cam=Camera.main??new GameObject("Main Camera").AddComponent<Camera>();cam.tag="MainCamera";cam.orthographic=true;cam.orthographicSize=7.4f;cam.backgroundColor=AtlasPalette.DeepInk;cam.transform.position=new Vector3(W/2f,H/2f,-10);BuildAudio();BuildUI();ShowTitle();}
    Sprite MakeSprite(int shape){var t=new Texture2D(32,32,TextureFormat.RGBA32,false){filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Abs(x-15.5f),dy=Mathf.Abs(y-15.5f);bool on=shape==0||(shape==1?dx*dx+dy*dy<225:dx+dy<15);t.SetPixel(x,y,on?Color.white:Color.clear);}t.Apply();return Sprite.Create(t,new Rect(0,0,32,32),new Vector2(.5f,.5f),32);}
    void BuildAudio(){sfx=gameObject.AddComponent<AudioSource>();sfx.playOnAwake=false;sfx.volume=.32f;ambient=gameObject.AddComponent<AudioSource>();ambient.loop=true;ambient.volume=.045f;ambient.clip=Tone("Wind",6f,70,true);ambient.Play();}
    AudioClip Tone(string name,float length,float frequency,bool noise=false){int rate=22050,n=Mathf.CeilToInt(rate*length);var data=new float[n];float brown=0;var random=new System.Random(name.GetHashCode());for(int i=0;i<n;i++){float fade=Mathf.Min(1,i/(rate*.01f),(n-i)/(rate*.01f));if(noise){brown=Mathf.Clamp(brown+((float)random.NextDouble()*2-1)*.025f,-.3f,.3f);data[i]=brown*fade;}else data[i]=Mathf.Sin(i*frequency*Mathf.PI*2/rate)*fade*Mathf.Exp(-4f*i/n);}var clip=AudioClip.Create(name,n,1,rate,false);clip.SetData(data,0);return clip;}

    void BuildUI(){if(FindFirstObjectByType<EventSystem>()==null)new GameObject("EventSystem",typeof(EventSystem),typeof(InputSystemUIInputModule));var canvas=new GameObject("Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var sc=canvas.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1440,900);sc.matchWidthOrHeight=.5f;
        var top=Box(canvas.transform,"Expedition Ledger",new Vector2(18,-18),new Vector2(720,112),new Vector2(0,1),new Vector2(0,1));hud=Label(top.transform,"Ledger","",22,TextAnchor.UpperLeft,new Vector2(20,-12),new Vector2(680,38));provisionBar=Bar(top.transform,"Provisions",new Vector2(20,-62),AtlasPalette.Gold);moraleBar=Bar(top.transform,"Morale",new Vector2(365,-62),AtlasPalette.Jade);
        var mission=Box(canvas.transform,"Mandate Panel",new Vector2(-18,-18),new Vector2(430,205),Vector2.one,Vector2.one);objective=Label(mission.transform,"Objective","",18,TextAnchor.UpperLeft,new Vector2(18,-14),new Vector2(395,174));
        var bottom=Box(canvas.transform,"Message Panel",new Vector2(0,20),new Vector2(920,84),new Vector2(.5f,0),new Vector2(.5f,0));message=Label(bottom.transform,"Message","",21,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(880,60));
        prompt=Label(canvas.transform,"Prompt","",20,TextAnchor.MiddleCenter,new Vector2(0,116),new Vector2(760,44));prompt.color=AtlasPalette.Gold;prompt.rectTransform.anchorMin=prompt.rectTransform.anchorMax=new Vector2(.5f,0);prompt.rectTransform.pivot=new Vector2(.5f,0);
        terrainReadout=Label(canvas.transform,"Terrain","",16,TextAnchor.LowerLeft,new Vector2(20,116),new Vector2(380,40));terrainReadout.color=AtlasPalette.FadedParchment;terrainReadout.rectTransform.anchorMin=terrainReadout.rectTransform.anchorMax=Vector2.zero;terrainReadout.rectTransform.pivot=Vector2.zero;
        titlePanel=Panel(canvas.transform,"Title",AtlasPalette.Scrim);var sun=new GameObject("Seventh Sun",typeof(RectTransform),typeof(Image));sun.transform.SetParent(titlePanel.transform,false);sun.GetComponent<RectTransform>().sizeDelta=new Vector2(150,150);sun.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,205);sun.GetComponent<Image>().sprite=circle;sun.GetComponent<Image>().color=AtlasPalette.Gold;var tt=Label(titlePanel.transform,"TitleText","ATLAS OF THE\nSEVENTH SUN",58,TextAnchor.MiddleCenter,new Vector2(0,55),new Vector2(1100,170));tt.color=AtlasPalette.Gold;Label(titlePanel.transform,"Sub","CHART THE UNKNOWN  •  TRADE WITH HONOR  •  RETURN WITH A LEGEND",20,TextAnchor.MiddleCenter,new Vector2(0,-60),new Vector2(1050,60));MakeButton(titlePanel.transform,"BEGIN EXPEDITION",new Vector2(0,-155),StartGame);
        pausePanel=Panel(canvas.transform,"Pause",AtlasPalette.Scrim);Label(pausePanel.transform,"PauseText","EXPEDITION PAUSED\n\nESC — Resume     R — Restart",34,TextAnchor.MiddleCenter,Vector2.zero,new Vector2(900,220));pausePanel.SetActive(false);endPanel=Panel(canvas.transform,"End",AtlasPalette.Scrim);endPanel.SetActive(false);}
    GameObject Box(Transform p,string n,Vector2 pos,Vector2 size,Vector2 anchor,Vector2 pivot){var go=new GameObject(n,typeof(RectTransform),typeof(Image),typeof(Outline));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;r.anchoredPosition=pos;r.sizeDelta=size;go.GetComponent<Image>().color=new Color(AtlasPalette.Ink.r,AtlasPalette.Ink.g,AtlasPalette.Ink.b,.88f);var o=go.GetComponent<Outline>();o.effectColor=new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.32f);o.effectDistance=new Vector2(2,-2);return go;}
    Image Bar(Transform p,string n,Vector2 pos,Color c){var bg=new GameObject(n+" Track",typeof(RectTransform),typeof(Image));bg.transform.SetParent(p,false);var r=bg.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=new Vector2(315,18);bg.GetComponent<Image>().color=AtlasPalette.DeepInk;var fill=new GameObject(n+" Fill",typeof(RectTransform),typeof(Image));fill.transform.SetParent(bg.transform,false);var f=fill.GetComponent<RectTransform>();f.anchorMin=Vector2.zero;f.anchorMax=Vector2.one;f.offsetMin=f.offsetMax=Vector2.zero;fill.GetComponent<Image>().color=c;Label(bg.transform,n,n.ToUpperInvariant(),13,TextAnchor.MiddleLeft,new Vector2(0,-18),new Vector2(315,18));return fill.GetComponent<Image>();}
    Text Label(Transform p,string n,string v,int size,TextAnchor a,Vector2 pos,Vector2 dims){var go=new GameObject(n,typeof(RectTransform),typeof(Text));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=dims;r.anchoredPosition=pos;var t=go.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=v;t.fontSize=size;t.alignment=a;t.color=AtlasPalette.Parchment;t.fontStyle=FontStyle.Bold;t.raycastTarget=false;return t;}
    GameObject Panel(Transform p,string n,Color c){var go=new GameObject(n,typeof(RectTransform),typeof(Image));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;go.GetComponent<Image>().color=c;return go;}
    void MakeButton(Transform p,string text,Vector2 pos,UnityEngine.Events.UnityAction action){var go=new GameObject(text,typeof(RectTransform),typeof(Image),typeof(Button),typeof(Outline));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=new Vector2(360,68);r.anchoredPosition=pos;go.GetComponent<Image>().color=AtlasPalette.Rust;go.GetComponent<Button>().onClick.AddListener(()=>{Play(.12f,520);action();});var o=go.GetComponent<Outline>();o.effectColor=AtlasPalette.Gold;o.effectDistance=new Vector2(2,-2);Label(go.transform,"Text",text,23,TextAnchor.MiddleCenter,Vector2.zero,r.sizeDelta);}

    void ShowTitle(){SetHUD(false);titlePanel.SetActive(true);}void SetHUD(bool a){hud.transform.parent.gameObject.SetActive(a);objective.transform.parent.gameObject.SetActive(a);message.transform.parent.gameObject.SetActive(a);prompt.gameObject.SetActive(a);terrainReadout.gameObject.SetActive(a);}void StartGame(){title=false;ended=false;paused=false;Time.timeScale=1;titlePanel.SetActive(false);endPanel.SetActive(false);pausePanel.SetActive(false);SetHUD(true);Generate();}
    void Generate(){foreach(var go in world)if(go)Destroy(go);world.Clear();fog.Clear();sites.Clear();rng=new System.Random(Environment.TickCount);map=new Terrain[W,H];trailRoot=NewWorld("Trail");for(int x=0;x<W;x++)for(int y=0;y<H;y++){float n=Mathf.PerlinNoise(x*.14f+3.7f,y*.14f+8.1f);Terrain t=x<4?Terrain.Sea:n<.31f?Terrain.Desert:n<.49f?Terrain.Plains:n<.69f?Terrain.Forest:Terrain.Mountain;map[x,y]=t;Tile(x,y,t);}pos=new Vector2Int(3,H/2);provisions=140;morale=75;gold=0;discoveries=0;days=1;AddSite(new Vector2Int(8,6),"River Confederacy",20,AtlasPalette.Jade);AddSite(new Vector2Int(16,16),"Sunstone Mission",28,AtlasPalette.Desert);AddSite(new Vector2Int(25,7),"Red Mesa Citadel",35,AtlasPalette.Rust);AddSite(new Vector2Int(30,17),"The Seventh City",90,AtlasPalette.Gold);explorer=SpriteObject("Explorer",circle,AtlasPalette.Gold,new Vector3(pos.x,pos.y,-.35f),.68f,8);AddMark(explorer.transform,diamond,AtlasPalette.Ink,.32f,9);Reveal();MarkTrail();SetMessage("Your ship anchors at Dawnwatch. The blank continent waits beyond the surf.");UpdateView(true);}
    GameObject NewWorld(string n){var go=new GameObject(n);world.Add(go);return go;}GameObject SpriteObject(string n,Sprite s,Color c,Vector3 at,float scale,int order){var go=NewWorld(n);var sr=go.AddComponent<SpriteRenderer>();sr.sprite=s;sr.color=c;sr.sortingOrder=order;go.transform.position=at;go.transform.localScale=Vector3.one*scale;return go;}void AddMark(Transform p,Sprite s,Color c,float scale,int order){var go=new GameObject("Ink mark",typeof(SpriteRenderer));go.transform.SetParent(p,false);go.transform.localScale=Vector3.one*scale;var sr=go.GetComponent<SpriteRenderer>();sr.sprite=s;sr.color=c;sr.sortingOrder=order;}
    void Tile(int x,int y,Terrain t){Color c=t switch{Terrain.Sea=>AtlasPalette.Sea,Terrain.Plains=>AtlasPalette.Plains,Terrain.Forest=>AtlasPalette.Forest,Terrain.Desert=>AtlasPalette.Desert,_=>AtlasPalette.Mountain};var tile=SpriteObject($"{t}_{x}_{y}",square,c,new Vector3(x,y,0),.97f,0);if((x+y*3)%4==0&&t!=Terrain.Sea){var m=new GameObject("Map mark",typeof(SpriteRenderer));m.transform.SetParent(tile.transform,false);m.transform.localPosition=new Vector3(0,0,-.05f);m.transform.localScale=Vector3.one*(t==Terrain.Mountain?.38f:.22f);var sr=m.GetComponent<SpriteRenderer>();sr.sprite=t==Terrain.Mountain?diamond:circle;sr.color=new Color(AtlasPalette.Ink.r,AtlasPalette.Ink.g,AtlasPalette.Ink.b,t==Terrain.Forest?.46f:.27f);sr.sortingOrder=1;}var f=SpriteObject("Uncharted",square,AtlasPalette.Fog,new Vector3(x,y,-.2f),.99f,5);fog[new Vector2Int(x,y)]=f;}
    void AddSite(Vector2Int p,string n,int value,Color c){var m=SpriteObject(n,diamond,c,new Vector3(p.x,p.y,-.12f),.78f,4);AddMark(m.transform,circle,AtlasPalette.Ink,.5f,5);sites.Add(new Site{p=p,name=n,gold=value,color=c,marker=m});}

    void Update(){pulse+=Time.unscaledDeltaTime;if(title){var img=titlePanel.transform.Find("Seventh Sun")?.GetComponent<Image>();if(img)img.color=new Color(AtlasPalette.Gold.r,AtlasPalette.Gold.g,AtlasPalette.Gold.b,.75f+Mathf.Sin(pulse*2)*.12f);return;}if(ended)return;var k=Keyboard.current;if(k==null)return;if(k.escapeKey.wasPressedThisFrame)TogglePause();if(paused){if(k.rKey.wasPressedThisFrame)StartGame();return;}moveCooldown-=Time.deltaTime;Vector2Int d=Vector2Int.zero;if(k.wKey.isPressed||k.upArrowKey.isPressed)d=Vector2Int.up;else if(k.sKey.isPressed||k.downArrowKey.isPressed)d=Vector2Int.down;else if(k.aKey.isPressed||k.leftArrowKey.isPressed)d=Vector2Int.left;else if(k.dKey.isPressed||k.rightArrowKey.isPressed)d=Vector2Int.right;if(d!=Vector2Int.zero&&moveCooldown<=0){Move(d);moveCooldown=.16f;}if(k.eKey.wasPressedThisFrame||k.spaceKey.wasPressedThisFrame)Interact();CameraMotion();foreach(var s in sites)if(!s.found&&s.marker)s.marker.transform.localScale=Vector3.one*(.76f+Mathf.Sin(Time.time*3+s.p.x)*.08f);}
    void TogglePause(){paused=!paused;Time.timeScale=paused?0:1;pausePanel.SetActive(paused);}int Cost(Terrain t)=>t switch{Terrain.Mountain=>4,Terrain.Forest=>2,Terrain.Sea=>2,_=>1};
    void Move(Vector2Int d){var n=pos+d;if(n.x<1||n.x>=W-1||n.y<1||n.y>=H-1){SetMessage("The expedition cannot cross the edge of the known world.");return;}int cost=Cost(map[n.x,n.y]);pos=n;days++;provisions-=cost;MarkTrail();Play(.07f,300+cost*50);if(rng.NextDouble()<.055){morale-=4;SetMessage("A difficult march tests the company. Morale falls by 4.");kick=.16f;}Reveal();UpdateView();if(provisions<=0||morale<=0)Finish(false,"The expedition can go no farther.");}
    void MarkTrail(){var dot=SpriteObject("Route mark",circle,new Color(AtlasPalette.Parchment.r,AtlasPalette.Parchment.g,AtlasPalette.Parchment.b,.42f),new Vector3(pos.x,pos.y,-.16f),.14f,3);dot.transform.SetParent(trailRoot.transform);}void Reveal(){for(int x=pos.x-2;x<=pos.x+2;x++)for(int y=pos.y-2;y<=pos.y+2;y++)if(fog.TryGetValue(new Vector2Int(x,y),out var f)){Destroy(f);fog.Remove(new Vector2Int(x,y));}}
    void Interact(){var site=sites.Find(s=>Vector2Int.Distance(s.p,pos)<1.5f&&!s.found);if(site!=null){site.found=true;discoveries++;gold+=site.gold;morale=Mathf.Min(100,morale+10);site.marker.transform.localScale*=1.35f;kick=.32f;Play(.35f,784);Burst(site.marker.transform.position,site.color);SetMessage($"{site.name} enters the atlas. Trade yields {site.gold} gold and restores 10 morale.");}else if(pos.x<=4){provisions=Mathf.Min(140,provisions+55);morale=Mathf.Min(100,morale+15);Play(.18f,520);SetMessage("Dawnwatch refits the expedition: +55 provisions, +15 morale.");if(gold>=120&&discoveries>=4)Finish(true,"You return with the Seventh City mapped and a legend secured.");}else SetMessage("No delegation waits here. Search for a glowing chart marker.");UpdateView();}
    void Burst(Vector3 c,Color color){for(int i=0;i<12;i++){float a=i*Mathf.PI*2/12;var p=SpriteObject("Discovery spark",diamond,color,c+new Vector3(Mathf.Cos(a),Mathf.Sin(a),-.4f)*.8f,.18f,10);Destroy(p,.7f);}}void Play(float length,float f){sfx.pitch=UnityEngine.Random.Range(.94f,1.06f);sfx.PlayOneShot(Tone("SFX"+f,length,f));}
    void CameraMotion(){var target=new Vector3(Mathf.Clamp(pos.x,7,W-7),Mathf.Clamp(pos.y,5,H-5),-10);cameraTarget=Vector3.Lerp(cameraTarget==Vector3.zero?target:cameraTarget,target,1-Mathf.Exp(-7*Time.deltaTime));if(kick>0){kick=Mathf.MoveTowards(kick,0,Time.deltaTime*1.6f);cameraTarget+=(Vector3)UnityEngine.Random.insideUnitCircle*kick;}cam.transform.position=cameraTarget;}
    void UpdateView(bool snap=false){if(explorer)explorer.transform.position=new Vector3(pos.x,pos.y,-.35f);var target=new Vector3(Mathf.Clamp(pos.x,7,W-7),Mathf.Clamp(pos.y,5,H-5),-10);if(snap){cameraTarget=target;cam.transform.position=target;}var terrain=map[pos.x,pos.y];int cost=Cost(terrain);hud.text=$"DAY {days:000}     GOLD {gold:000}     DISCOVERIES {discoveries}/4";provisionBar.rectTransform.anchorMax=new Vector2(Mathf.Clamp01(provisions/140f),1);moraleBar.rectTransform.anchorMax=new Vector2(Mathf.Clamp01(morale/100f),1);provisionBar.color=provisions<30?AtlasPalette.Danger:AtlasPalette.Gold;moraleBar.color=morale<25?AtlasPalette.Danger:AtlasPalette.Jade;objective.text=$"THE CROWN'S MANDATE\n\n◈ Chart all four sites   {discoveries}/4\n◈ Secure 120 gold        {gold}/120\n◈ Return west to Dawnwatch\n\nE / SPACE — interact";terrainReadout.text=$"{terrain.ToString().ToUpperInvariant()}  •  NEXT STEP COST: {cost} PROVISIONS";var near=sites.Find(s=>Vector2Int.Distance(s.p,pos)<1.5f&&!s.found);prompt.text=near!=null?$"E / SPACE  —  PARLEY AT {near.name.ToUpperInvariant()}":pos.x<=4?"E / SPACE  —  RESUPPLY AT DAWNWATCH":"";}
    void SetMessage(string s){message.text=s;CancelInvoke(nameof(ClearMessage));Invoke(nameof(ClearMessage),5);}void ClearMessage(){if(message)message.text="";}void Finish(bool win,string reason){ended=true;Time.timeScale=1;endPanel.SetActive(true);foreach(Transform c in endPanel.transform)Destroy(c.gameObject);Play(.5f,win?659:180);var r=Label(endPanel.transform,"Result",(win?"THE ATLAS IS COMPLETE":"THE EXPEDITION IS LOST")+"\n\n"+reason+$"\n\nDAYS {days}   •   GOLD {gold}   •   SITES {discoveries}/4",38,TextAnchor.MiddleCenter,new Vector2(0,70),new Vector2(1100,340));r.color=win?AtlasPalette.Gold:AtlasPalette.Danger;MakeButton(endPanel.transform,"SAIL AGAIN",new Vector2(0,-155),StartGame);}
}
